export function getSearchToToolSharedCopy(locale: string): SharedCopy {
  return shared[getValidLocale(locale)]
}

export function getSearchToToolLandingCopy(locale: string, routeId: SearchToToolRouteId): SearchToToolLandingCopy {
  const resolved = getValidLocale(locale)
  const base = resolved === 'en' ? en[routeId] : localized[resolved][routeId]
  const common = shared[resolved]
  return {
    ...base,
    principles: common.principles,
    ctaLabels: common.ctaLabels,
    faqEyebrow: common.nextStep,
    faqTitle: common.commonQuestions,
  }
}

export function getGlassesGuideHubCopy(locale: string): GlassesGuideHubCopy {
  return hub[getValidLocale(locale)]
}
